const REVIEW_UI={
  en:{readMore:"Read full review",google:"View this profile on Google →",close:"Close"},
  de:{readMore:"Vollständige Bewertung lesen",google:"Dieses Profil auf Google ansehen →",close:"Schließen"},
  fr:{readMore:"Lire l’avis complet",google:"Voir ce profil sur Google →",close:"Fermer"},
  es:{readMore:"Leer reseña completa",google:"Ver este perfil en Google →",close:"Cerrar"},
  it:{readMore:"Leggi la recensione completa",google:"Visualizza questo profilo su Google →",close:"Chiudi"},
  ms:{readMore:"Baca ulasan penuh",google:"Lihat profil ini di Google →",close:"Tutup"},
  ja:{readMore:"レビュー全文を読む",google:"Googleでこのプロフィールを見る →",close:"閉じる"}
};

/* All seven supported languages have their own dictionary in this build. */
function applyLanguage(lang){
  const t=translations[lang]||translations.en;
  const ui=REVIEW_UI[lang]||REVIEW_UI.en;
  document.documentElement.lang=translations[lang]?lang:"en";
  document.querySelectorAll("[data-i18n]").forEach(el=>{
    const key=el.getAttribute("data-i18n");
    if(Object.prototype.hasOwnProperty.call(t,key)) el.textContent=t[key];
  });
  document.querySelectorAll("[data-i18n-placeholder]").forEach(el=>{
    const key=el.getAttribute("data-i18n-placeholder");
    if(Object.prototype.hasOwnProperty.call(t,key)) el.placeholder=t[key];
  });
  const select=document.getElementById("languageSelect");
  if(select) select.value=translations[lang]?lang:"en";
  const close=document.getElementById("reviewModalClose");
  if(close){close.setAttribute("aria-label",ui.close);close.title=ui.close;}
  const google=document.querySelector("[data-i18n=reviewModalGoogle]");
  if(google) google.textContent=ui.google;
}

function escapeHtml(value){
  return String(value).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;");
}

function renderReviews(){
  const grid=document.getElementById("reviewGrid");
  grid.innerHTML="";
  const populated=REVIEWS.filter(r=>r.text&&r.author);
  const lang=document.documentElement.lang||"en";
  const ui=REVIEW_UI[lang]||REVIEW_UI.en;
  populated.forEach((review,index)=>{
    const article=document.createElement("article");
    article.className="review";
    const excerpt=review.text.replace(/\s+/g," ").trim();
    const safeExcerpt=escapeHtml(excerpt);
    article.innerHTML=`<div class="stars">★★★★★</div><div class="review-text"><p>“${safeExcerpt}”</p></div><button class="review-more" type="button" data-review-index="${index}">${escapeHtml(ui.readMore)} →</button><div class="review-author">${escapeHtml(review.author)}</div><div class="review-source">${escapeHtml(review.source||"Google Review")}</div>`;
    grid.appendChild(article);
  });
  grid.querySelectorAll(".review-more").forEach(button=>button.addEventListener("click",()=>openReview(Number(button.dataset.reviewIndex))));
}

function openReview(index){
  const review=REVIEWS.filter(r=>r.text&&r.author)[index];
  if(!review) return;
  document.getElementById("reviewModalTitle").textContent=review.author;
  document.getElementById("reviewModalText").textContent=`“${review.text}”`;
  document.getElementById("reviewModalAuthor").textContent=review.author;
  document.getElementById("reviewModalSource").textContent=review.source||"Google Review";
  const modal=document.getElementById("reviewModal");
  if(typeof modal.showModal==="function") modal.showModal();
  else modal.setAttribute("open","");
}

const menuBtn=document.getElementById("menuBtn"),navLinks=document.getElementById("navLinks");
menuBtn.addEventListener("click",()=>{
  const open=navLinks.classList.toggle("open");
  menuBtn.setAttribute("aria-expanded",String(open));
  menuBtn.textContent=open?"×":"☰";
  document.body.classList.toggle("menu-open",open);
});
document.querySelectorAll(".nav-links a").forEach(link=>link.addEventListener("click",()=>{
  navLinks.classList.remove("open");menuBtn.setAttribute("aria-expanded","false");menuBtn.textContent="☰";document.body.classList.remove("menu-open");
}));
document.getElementById("languageSelect").addEventListener("change",e=>{applyLanguage(e.target.value);renderReviews();});
document.getElementById("year").textContent=new Date().getFullYear();
applyLanguage("en");
renderReviews();

const reviewModal=document.getElementById("reviewModal");
document.getElementById("reviewModalClose").addEventListener("click",()=>reviewModal.close());
reviewModal.addEventListener("click",e=>{if(e.target===reviewModal) reviewModal.close()});

const topBtn=document.getElementById("topBtn");
window.addEventListener("scroll",()=>topBtn.classList.toggle("show",window.scrollY>650),{passive:true});
topBtn.addEventListener("click",()=>window.scrollTo({top:0,behavior:"smooth"}));


// V5 lightweight scroll reveal. No animation library required.
document.addEventListener("DOMContentLoaded",()=>{
  document.body.classList.add("reveal-ready");
  const targets=document.querySelectorAll(".section-head,.trust-card,.about-grid,.cards .card,.journeys .journey,.service-band,.why-grid .why,.reviews-wrap,.vehicle-media,.vehicle > div:last-child,.steps .step,.sunspire-box,.faq details,.contact-grid > *");
  targets.forEach((el,i)=>{el.classList.add("reveal"); if(i%4===1)el.classList.add("reveal-delay-1"); else if(i%4===2)el.classList.add("reveal-delay-2"); else if(i%4===3)el.classList.add("reveal-delay-3");});
  const io=new IntersectionObserver((entries,observer)=>{
    entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add("is-visible");observer.unobserve(entry.target);}});
  },{threshold:.12,rootMargin:"0px 0px -35px 0px"});
  document.querySelectorAll(".reveal").forEach(el=>io.observe(el));
});


