  en:{readMore:"Read full review",google:"View this profile on Google →",close:"Close",translated:"Google review"},
  de:{readMore:"Vollständige Bewertung lesen",google:"Dieses Profil auf Google ansehen →",close:"Schließen",translated:"Google-Bewertung · Website-Übersetzung"},
